```json
{
  "root_causes": [
    {
      "service": "ts-travel-plan-service",
      "fault_kind": "http_slow",
      "evidence": [
        {"kind": "trace", "sql": "SELECT c.service_name AS caller, c.span_name, s.span_name AS callee_path, count(*) AS n, round(approx_quantile(c.duration/1e6,0.5),1) AS client_med_ms, round(approx_quantile(s.duration/1e6,0.5),1) AS server_med_ms FROM abnormal_traces c JOIN abnormal_traces s ON s.parent_span_id=c.span_id AND s.trace_id=c.trace_id WHERE c.service_name='ts-travel-plan-service' AND c.attr_span_kind='Client' AND s.span_name LIKE 'GET /api/v1/trainservice%' GROUP BY ALL", "claim": "Abnormal: all 182 travel-plan GET calls to train-service take about 614 ms client-side while the server span takes about 5 ms."},
        {"kind": "trace", "sql": "SELECT c.service_name AS caller, c.span_name, s.span_name AS callee_path, count(*) AS n, round(approx_quantile(c.duration/1e6,0.5),1) AS client_med_ms, round(approx_quantile(s.duration/1e6,0.5),1) AS server_med_ms FROM normal_traces c JOIN normal_traces s ON s.parent_span_id=c.span_id AND s.trace_id=c.trace_id WHERE c.service_name='ts-travel-plan-service' AND c.attr_span_kind='Client' AND s.span_name LIKE 'GET /api/v1/trainservice%' GROUP BY ALL", "claim": "Normal baseline: the same travel-plan GET calls to train-service have a client median of about 6 ms."},
        {"kind": "trace", "sql": "SELECT c.span_name AS client_span, s.span_name AS server_span, count(*) AS n, round(approx_quantile(c.duration/1e6,0.5),1) AS client_med_ms FROM abnormal_traces c JOIN abnormal_traces s ON s.parent_span_id=c.span_id AND s.trace_id=c.trace_id WHERE c.service_name='ts-travel-plan-service' AND c.attr_span_kind='Client' AND s.service_name='ts-seat-service' GROUP BY ALL", "claim": "Travel-plan POST calls to seat-service on a different path stay near baseline (about 21 ms median), so the slowdown is path-specific."}
      ]
    }
  ],
  "propagation": [
    {"from": "ts-travel-plan-service", "to": "ts-ui-dashboard", "evidence": [
      {"kind": "trace", "sql": "SELECT service_name, span_name, attr_span_kind, count(*) AS n, round(approx_quantile(duration/1e6,0.95),1) AS p95_ms FROM abnormal_traces WHERE service_name IN ('ts-travel-plan-service','ts-ui-dashboard') AND span_name LIKE '%travelPlan%' AND attr_span_kind='Server' GROUP BY ALL", "claim": "User-facing ui-dashboard travelPlan requests and travel-plan server spans both show multi-second p95 latency in the abnormal period."}
    ]}
  ]
}
```

